<template>
  <div class="tool-approval-toggle row items-center q-ml-sm">
    <q-toggle
      :model-value="effectiveCritical"
      :disable="!overridable"
      color="amber-8"
      keep-color
      size="sm"
      :title="toggleTitle"
      @update:model-value="onToggle"
    />
    <q-icon
      v-if="hasOverride"
      name="push_pin"
      size="11px"
      class="q-ml-xs tool-approval-toggle__pin"
      :title="$t('tool_approval_override_active') || 'Override active'"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, PropType } from 'vue';
import { useI18n } from 'vue-i18n';
import { useAgentsStore } from 'src/store/Settings/agents.store';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'ToolApprovalToggle',

  props: {
    toolName: { type: String, required: true },
    /** ``null`` on the create-wizard surface (agent doesn't exist
     *  yet).  In that mode writes go to ``localOverrides`` and
     *  are persisted by the wizard's main Save button.  When set,
     *  writes hit the backend immediately. */
    agentId: { type: String as PropType<string | null>, default: null },
    /** Current ``approval_mode`` of the agent.  Under ``all`` /
     *  ``none`` the toggle is disabled because per-tool overrides
     *  don't apply (the mode forces every tool's gating). */
    approvalMode: { type: String, default: 'critical' },
    /** Buffered ``tool_approvals`` map for the wizard.  Ignored
     *  when ``agentId`` is set. */
    localOverrides: {
      type: Object as PropType<Record<string, boolean> | null>,
      default: null,
    },
  },

  emits: ['update:localOverrides'],

  setup(props, { emit }) {
    const agentsStore = useAgentsStore();
    const { t } = useI18n();

    /** Where overrides go: backend (immediate, profile) or local
     *  buffer (deferred, wizard).  Independent of approval mode —
     *  the user can configure the per-tool policy any time, even
     *  if the current mode (``all`` / ``none``) makes it inert at
     *  runtime.  The toggle's tooltip surfaces that fact. */
    const overridable = computed(
      () => !!props.agentId || props.localOverrides !== null,
    );

    /** Source-of-truth override map. */
    const overrides = computed<Record<string, boolean>>(() => {
      if (props.agentId) {
        return agentsStore.getToolApprovalsForAgent(props.agentId);
      }
      return props.localOverrides || {};
    });

    const hasOverride = computed(() => props.toolName in overrides.value);

    /** Inherent default for this tool (without any override). */
    const defaultCritical = computed(() =>
      agentsStore.isCriticalTool(props.toolName),
    );

    /** Per-tool *configured* gating — drives the toggle position.
     *  Reflects what the user has set up for this tool (default
     *  + override), not what the runtime will do given the mode.
     *  The mode-effect note lives in the tooltip. */
    const effectiveCritical = computed(() => {
      if (props.toolName in overrides.value) {
        return overrides.value[props.toolName] === true;
      }
      return defaultCritical.value;
    });

    const toggleTitle = computed(() => {
      if (!overridable.value) return '';
      const baseLabel = effectiveCritical.value
        ? 'Critical — requires human approval. Click to mark as auto-execute.'
        : 'Auto-execute — runs without approval. Click to mark as critical.';
      if (props.approvalMode === 'all') {
        return `${baseLabel} (Note: approval mode is 'All' — every tool currently gates regardless of this setting.)`;
      }
      if (props.approvalMode === 'none') {
        return `${baseLabel} (Note: approval mode is 'None' — no tool currently gates regardless of this setting.)`;
      }
      return baseLabel;
    });

    /** Decide what to write.  If the new value matches the inherent
     *  default, clear the override (so the row goes back to default
     *  and the pin disappears).  Otherwise write the override. */
    const writeValue = (newCritical: boolean): boolean | null => {
      if (newCritical === defaultCritical.value) return null;
      return newCritical;
    };

    const persistViaStore = async (next: boolean | null) => {
      if (!props.agentId) return;
      try {
        if (next === null) {
          await agentsStore.clearToolApproval(props.agentId, props.toolName);
        } else {
          await agentsStore.setToolApproval(props.agentId, props.toolName, next);
        }
        notify.success(t('MSG_SAVE'));
      } catch (err) {
        console.error('[ToolApprovalToggle] failed to save override:', err);
        notify.error(t('approval_toggle_failed') || 'Failed to save');
      }
    };

    const persistToBuffer = (next: boolean | null) => {
      if (props.localOverrides === null) return;
      const updated = { ...props.localOverrides };
      if (next === null) {
        delete updated[props.toolName];
      } else {
        updated[props.toolName] = next;
      }
      emit('update:localOverrides', updated);
    };

    const onToggle = (newCritical: boolean) => {
      if (!overridable.value) return;
      const next = writeValue(newCritical);
      if (props.agentId) {
        void persistViaStore(next);
      } else {
        persistToBuffer(next);
      }
    };

    return {
      overridable,
      hasOverride,
      effectiveCritical,
      toggleTitle,
      onToggle,
    };
  },
});
</script>

<style lang="scss" scoped>
.tool-approval-toggle {
  flex-shrink: 0;

  &__pin {
    color: var(--q-primary);
    opacity: 0.75;
  }
}
</style>
