<template>
  <div class="mcp-tool-selector">
    <!-- Skills section — grouped tree view (one card per skill,
         tools nested inside).  The header shows the active /
         total tool count.  The "Managed by skills" caption that
         used to live here is gone: the section *is* the skill
         grouping now, no need to label it twice. -->
    <div v-if="builtInToolGroups.length" class="mcp-server-list q-mb-md">
      <div class="mcp-section-label">
        <q-icon name="build" size="14px" class="q-mr-xs text-grey-7" />
        <q-badge
          color="primary"
          :label="`${activeBuiltInCount} / ${totalBuiltInCount} ${$t('docnet_tools') || 'Tools'}`"
        />
      </div>

      <!-- Section explainer — one sentence at the top tells the
           user what the per-row toggle does so they don't have
           to learn it row-by-row.  Replaces a heavier legend
           strip; tooltips on individual rows still provide the
           longer explanation. -->
      <p class="mcp-tool-explainer">
        {{
          $t('tools_explainer')
            || 'Critical tools pause for human approval. Toggle a tool to override its default policy for this agent.'
        }}
      </p>

      <q-card
        v-for="group in builtInToolGroups"
        :key="group.skillType"
        flat
        bordered
        class="mcp-server-card"
        :class="{ 'mcp-server-card--has-selected': group.active }"
      >
        <q-card-section class="mcp-server-header" @click="toggleExpanded(`builtin:${group.skillType}`)">
          <div class="mcp-server-header__left">
            <!-- Group toggle checkbox — same affordance as the
                 skill cards.  Tri-state: checked = all tools on,
                 unchecked = all off, intermediate = some on.
                 Suppressed for the locked ``_always`` group whose
                 tools can't be toggled. -->
            <q-checkbox
              v-if="group.skillType !== '_always'"
              :model-value="
                group.tools.every(t => t.active)
                  ? true
                  : group.tools.some(t => t.active)
                    ? null
                    : false
              "
              :toggle-indeterminate="false"
              :disable="readOnlySelection"
              size="sm"
              color="primary"
              class="mcp-server-header__checkbox"
              @update:model-value="(val) => !readOnlySelection && toggleAllInGroup(group, val)"
              @click.stop
            />
            <q-icon
              :name="expanded[`builtin:${group.skillType}`] ? 'expand_more' : 'chevron_right'"
              size="20px"
              class="mcp-server-header__chevron"
            />
            <div>
              <div class="mcp-server-header__name" :class="{ 'text-grey-5': !group.active }">{{ group.skill }}</div>
            </div>
          </div>
          <div class="mcp-server-header__right">
            <q-badge
              :color="group.active ? 'positive' : 'grey-4'"
              :text-color="group.active ? 'white' : 'grey-7'"
              :label="`${group.tools.filter(t => t.active).length} / ${group.tools.length}`"
            />
          </div>
        </q-card-section>

        <q-slide-transition>
          <div v-show="expanded[`builtin:${group.skillType}`]">
            <q-separator />
            <q-card-section class="mcp-tools-section">
              <!-- Column header — names the toggle column once
                   per group instead of via tooltips on every row.
                   Hidden when the group has no toggleable rows. -->
              <div
                v-if="group.tools.some(t => !t.locked)"
                class="mcp-tools-header"
              >
                <q-space />
                <span class="text-caption text-grey-6">
                  {{ $t('critical') || 'Critical' }}
                </span>
              </div>
              <div class="mcp-tools-grid">
                <div
                  v-for="tool in group.tools"
                  :key="tool.name"
                  class="mcp-tool-item"
                  :class="{
                    'mcp-tool-item--builtin': tool.active,
                    'mcp-tool-item--inactive': !tool.active,
                    'mcp-tool-item--clickable': !tool.locked && !readOnlySelection,
                  }"
                  @click="!tool.locked && !readOnlySelection && toggleBuiltInTool(tool.name, !tool.active)"
                >
                  <q-icon
                    v-if="tool.locked"
                    name="lock"
                    size="18px"
                    color="grey-5"
                    class="q-mr-sm"
                  />
                  <q-icon
                    v-else
                    :name="tool.active ? 'check_circle' : 'radio_button_unchecked'"
                    size="18px"
                    :color="tool.active ? 'positive' : 'grey-5'"
                    class="q-mr-sm"
                  />
                  <div class="mcp-tool-info">
                    <div class="mcp-tool-name-row" :class="{ 'text-grey-5': !tool.active }">
                      <!-- Same chip the skill cards render: warning
                           icon + name + ``Critical`` badge when the
                           tool is critical (default OR pinned via
                           override), wrench + name otherwise.
                           Read-only here — the toggle on the right
                           is what flips the override. -->
                      <q-chip
                        dense
                        size="sm"
                        :color="effectiveCritical(tool.name) ? 'amber-2' : 'grey-3'"
                        :text-color="effectiveCritical(tool.name) ? 'amber-10' : 'grey-8'"
                        class="tool-chip"
                      >
                        <q-icon
                          :name="effectiveCritical(tool.name) ? 'warning' : 'build'"
                          size="12px"
                          class="q-mr-xs"
                        />
                        {{ toolLabelFor(tool.name) }}
                        <span
                          v-if="effectiveCritical(tool.name)"
                          class="q-ml-xs tool-chip__suffix"
                        >
                          · {{ $t('critical') || 'Critical' }}
                        </span>
                        <q-icon
                          v-if="hasOverride(tool.name)"
                          name="push_pin"
                          size="9px"
                          class="q-ml-xs tool-chip__pin"
                        />
                      </q-chip>
                    </div>
                  </div>
                  <!-- Explicit critical / non-critical toggle.
                       Renders for selected, non-locked tools.
                       Persists immediately when ``agentId`` is set
                       (profile auto-save), buffered otherwise. -->
                  <ToolApprovalToggle
                    v-if="tool.active && !tool.locked"
                    :tool-name="tool.name"
                    :agent-id="agentId"
                    :approval-mode="approvalMode"
                    :local-overrides="localOverrides"
                    @update:local-overrides="$emit('update:localOverrides', $event)"
                  />
                  <q-tooltip v-if="tool.locked">{{ $t('always_included_tooltip') || 'This tool is always available and cannot be disabled' }}</q-tooltip>
                </div>
              </div>
            </q-card-section>
          </div>
        </q-slide-transition>
      </q-card>
    </div>

    <!-- MCP Servers section — disabled for current release. SDK cleanup
         path leaves dangling async tasks on upstream 502s, killing the
         Celery worker silently. Re-enable with the backend registry. -->
    <div v-if="false" class="mcp-section-label">
      <q-icon name="dns" size="16px" class="q-mr-xs" />
      {{ $t('mcp_servers') || 'MCP Servers' }}
    </div>

    <!-- Loading state -->
    <div v-if="false && loading" class="mcp-loading">
      <q-spinner color="primary" size="2em" />
      <span class="q-ml-sm">{{ $t('loading_mcp_servers') }}</span>
    </div>

    <!-- Error state -->
    <div v-else-if="false && loadError" class="mcp-error">
      <q-icon name="warning" color="negative" size="sm" class="q-mr-sm" />
      <span>{{ loadError }}</span>
      <q-btn flat dense no-caps color="primary" :label="$t('retry')" class="q-ml-sm" @click="loadServers" />
    </div>

    <!-- Empty state -->
    <div v-else-if="false && !servers.length" class="mcp-empty">
      <q-icon name="extension_off" size="48px" color="grey-5" />
      <div class="text-subtitle1 q-mt-sm text-grey-7">{{ $t('no_mcp_servers') }}</div>
      <div class="text-caption text-grey-6">{{ $t('no_mcp_servers_desc') }}</div>
    </div>

    <!-- Server groups -->
    <div v-else-if="false" class="mcp-server-list">
      <q-card
        v-for="server in servers"
        :key="server.id"
        flat
        bordered
        class="mcp-server-card"
        :class="{ 'mcp-server-card--has-selected': getSelectedToolCount(server.id) > 0 }"
      >
        <!-- Server header -->
        <q-card-section class="mcp-server-header" @click="toggleExpanded(server.id)">
          <div class="mcp-server-header__left">
            <q-icon
              :name="expanded[server.id] ? 'expand_more' : 'chevron_right'"
              size="20px"
              class="mcp-server-header__chevron"
            />
            <div>
              <div class="mcp-server-header__name">{{ server.name }}</div>
              <div v-if="server.description" class="mcp-server-header__desc">{{ server.description }}</div>
            </div>
          </div>
          <div class="mcp-server-header__right">
            <q-badge
              v-if="getSelectedToolCount(server.id) > 0"
              color="primary"
              :label="`${getSelectedToolCount(server.id)} / ${server.tools.length}`"
            />
            <q-badge
              v-else
              color="grey-4"
              text-color="grey-7"
              :label="`${server.tools.length} ${$t('docnet_tools')}`"
            />
            <q-chip
              v-if="server.status === 'ok'"
              size="xs"
              color="positive"
              text-color="white"
              :label="$t('connected')"
              dense
            />
            <q-chip
              v-else
              size="xs"
              color="warning"
              text-color="white"
              :label="server.status"
              dense
            />
          </div>
        </q-card-section>

        <!-- Tools list (collapsible) -->
        <q-slide-transition>
          <div v-show="expanded[server.id]">
            <q-separator />
            <q-card-section class="mcp-tools-section">
              <!-- Select all toggle -->
              <div class="mcp-select-all">
                <q-checkbox
                  :model-value="isAllSelected(server.id) ? true : (isPartiallySelected(server.id) ? null : false)"
                  :toggle-indeterminate="false"
                  color="primary"
                  size="sm"
                  @update:model-value="() => toggleAllTools(server.id, !isAllSelected(server.id))"
                />
                <span class="text-caption text-grey-7">{{ $t('select_all') }}</span>
              </div>

              <div class="mcp-tools-grid">
                <div
                  v-for="tool in server.tools"
                  :key="tool.name"
                  class="mcp-tool-item"
                  :class="{ 'mcp-tool-item--selected': isToolSelected(server.id, tool.name) }"
                >
                  <q-checkbox
                    :model-value="isToolSelected(server.id, tool.name)"
                    color="primary"
                    size="sm"
                    @update:model-value="(val) => toggleTool(server.id, tool.name, val)"
                  />
                  <div class="mcp-tool-info">
                    <div class="mcp-tool-name">{{ toolLabelFor(tool.name) }}</div>
                    <div v-if="tool.description" class="mcp-tool-desc">{{ tool.description }}</div>
                  </div>
                </div>
              </div>
            </q-card-section>
          </div>
        </q-slide-transition>
      </q-card>
    </div>

    <!-- Selected MCP tools summary -->
    <div v-if="false && totalSelectedCount > 0" class="mcp-summary q-mt-lg">
      <div class="text-subtitle2">{{ $t('selected_tools') }}: {{ totalSelectedCount }}</div>
      <div class="mcp-summary-chips">
        <template v-for="(tools, serverId) in localMcpServers" :key="serverId">
          <q-chip
            v-for="tool in tools"
            :key="`${serverId}:${tool}`"
            removable
            color="primary"
            text-color="white"
            size="sm"
            @remove="toggleTool(serverId, tool, false)"
          >
            {{ toolLabelFor(tool) }}
          </q-chip>
        </template>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { agentApiService } from 'src/services';
import type { McpServerInfo } from 'src/@types/agents';
import { skillLabel, toolLabel } from 'src/pages/DocNet/shared/docnet-labels';
import { useAgentsStore } from 'src/store/Settings/agents.store';
import ToolApprovalToggle from './ToolApprovalToggle.vue';

export default defineComponent({
  name: 'McpToolSelector',

  components: { ToolApprovalToggle },

  props: {
    modelValue: {
      type: Object as PropType<Record<string, string[]>>,
      required: true,
    },
    skills: {
      type: Array as PropType<Array<{ skill_type: string; is_enabled: boolean }>>,
      default: () => [],
    },
    /**
     * Skill definitions from GET /agents/skills — each entry carries the
     * `tools` list that belongs to that skill. Single source of truth,
     * kept in sync with SKILL_TOOL_MAPPING in the backend automatically.
     */
    availableSkills: {
      type: Array as PropType<Array<{ id: string; name?: string; tools?: string[] }>>,
      default: () => [],
    },
    disabledTools: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
    mcpTools: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
    /** Agent id when editing — needed to read/write per-tool overrides. */
    agentId: {
      type: String as PropType<string | null>,
      default: null,
    },
    /** Current ``approval_mode`` — controls whether overrides apply. */
    approvalMode: {
      type: String,
      default: 'critical',
    },
    /** Buffered ``tool_approvals`` map for the create wizard. */
    localOverrides: {
      type: Object as PropType<Record<string, boolean> | null>,
      default: null,
    },
    /** When ``true``, tool *selection* is read-only — row clicks and
     *  the group-header checkbox no-op, locked iconography reflects
     *  the constraint.  Per-tool approval toggles stay interactive
     *  so admins can still tighten/loosen gating per org.  Used for
     *  system agents whose tool list is shared across every org and
     *  must not be mutated through the generic PUT endpoint (the
     *  backend returns 403 for tool/skill writes on system agents). */
    readOnlySelection: {
      type: Boolean,
      default: false,
    },
  },

  emits: [
    'update:modelValue',
    'update:disabledTools',
    'update:mcpTools',
    // Flat, deduped array of effective tool names (what the agent will
    // actually have after skill + toggle resolution). Emitted on every
    // toggle so the parent can persist it to agent.tools without
    // re-deriving from skills.
    'update:tools',
    'update:localOverrides',
  ],

  setup() {
    // Store fallback: callers that don't pass ``available-skills`` (e.g.
    // McpToolSelector mounted standalone in the DocNet agent profile)
    // still need the skill→tools map. Read from the store instead of
    // hardcoding a duplicate of SKILL_TOOL_MAPPING here.
    return { agentsStore: useAgentsStore() };
  },

  data() {
    return {
      servers: [] as McpServerInfo[],
      loading: false,
      loadError: null as string | null,
      expanded: {} as Record<string, boolean>,
      localMcpServers: {} as Record<string, string[]>,
      localDisabledTools: [] as string[],
      localMcpTools: [] as string[],
    };
  },

  computed: {
    /** Set of skill_type keys that are enabled on this agent */
    enabledSkillTypes(): Set<string> {
      const set = new Set<string>();
      for (const skill of (this.skills || [])) {
        if (skill.is_enabled) set.add(skill.skill_type);
      }
      return set;
    },

    /** Set of built-in tool names explicitly added via mcp_tools (overriding skill state) */
    explicitBuiltInTools(): Set<string> {
      return new Set(this.localMcpTools);
    },

    /** Skill→tools definitions. Prefer the prop when it actually carries
     * tools (i.e. the API response made it through). A tools-less prop
     * means the parent is rendering a placeholder before skills load —
     * fall back to the store, which the component refreshes on mount.
     */
    effectiveAvailableSkills(): Array<{ id: string; name?: string; tools?: string[] }> {
      const propHasTools = (this.availableSkills || []).some(
        (d: { tools?: string[] }) => (d.tools || []).length > 0,
      );
      if (propHasTools) return this.availableSkills;
      return this.agentsStore.availableSkills || [];
    },

    /** All possible built-in tool groups with active state per tool.
     * Driven by ``availableSkills`` from the GET /agents/skills API so
     * adding a tool to SKILL_TOOL_MAPPING in the backend surfaces here
     * without any frontend change.
     */
    builtInToolGroups(): Array<{ skill: string; skillType: string; active: boolean; tools: Array<{ name: string; active: boolean; locked: boolean }> }> {
      const ALWAYS_INCLUDED = new Set(['request_human_approval']);
      const disabledSet = new Set(this.localDisabledTools);
      const explicitlyEnabled = new Set(this.explicitBuiltInTools);
      const groups: Array<{ skill: string; skillType: string; active: boolean; tools: Array<{ name: string; active: boolean; locked: boolean }> }> = [];
      const seen = new Set<string>();

      for (const def of this.effectiveAvailableSkills) {
        const skillType = def.id;
        const toolNames = def.tools || [];
        const skillEnabled = this.enabledSkillTypes.has(skillType);
        const tools: Array<{ name: string; active: boolean; locked: boolean }> = [];
        for (const name of toolNames) {
          if (!seen.has(name)) {
            seen.add(name);
            // Active if: (skill enabled AND not disabled) OR explicitly added via mcp_tools
            const active = (skillEnabled && !disabledSet.has(name)) || explicitlyEnabled.has(name);
            tools.push({ name, active, locked: false });
          }
        }
        if (tools.length) {
          const anyActive = tools.some((t) => t.active);
          groups.push({ skill: skillLabel(this.$t, skillType), skillType, active: anyActive, tools });
        }
      }

      // Always-included tools (locked, can't be disabled)
      const alwaysTools: Array<{ name: string; active: boolean; locked: boolean }> = [];
      for (const name of ALWAYS_INCLUDED) {
        if (!seen.has(name)) {
          alwaysTools.push({ name, active: true, locked: true });
        }
      }
      if (alwaysTools.length) {
        groups.push({
          skill: this.$t('always_available_skill'),
          skillType: '_always',
          active: true,
          tools: alwaysTools,
        });
      }

      return groups;
    },

    /** Flat list of active built-in tool names (for MCP tool dedup) */
    builtInToolNames(): Set<string> {
      const set = new Set<string>();
      for (const group of this.builtInToolGroups) {
        for (const tool of group.tools) {
          if (tool.active) set.add(tool.name);
        }
      }
      return set;
    },

    activeBuiltInCount(): number {
      let count = 0;
      for (const group of this.builtInToolGroups) {
        for (const tool of group.tools) {
          if (tool.active) count++;
        }
      }
      return count;
    },

    totalBuiltInCount(): number {
      let count = 0;
      for (const group of this.builtInToolGroups) {
        count += group.tools.length;
      }
      return count;
    },

    totalSelectedCount(): number {
      return Object.values(this.localMcpServers as Record<string, string[]>).reduce(
        (sum: number, tools: string[]) => sum + tools.length,
        0,
      );
    },
  },

  watch: {
    modelValue: {
      handler(val: Record<string, string[]>) {
        const incoming = JSON.stringify(val || {});
        if (incoming !== JSON.stringify(this.localMcpServers)) {
          this.localMcpServers = JSON.parse(incoming);
        }
      },
      immediate: true,
      deep: true,
    },
    disabledTools: {
      handler(val: string[]) {
        const incoming = JSON.stringify(val || []);
        if (incoming !== JSON.stringify(this.localDisabledTools)) {
          this.localDisabledTools = JSON.parse(incoming);
        }
      },
      immediate: true,
      deep: true,
    },
    mcpTools: {
      handler(val: string[]) {
        const incoming = JSON.stringify(val || []);
        if (incoming !== JSON.stringify(this.localMcpTools)) {
          this.localMcpTools = JSON.parse(incoming);
        }
      },
      immediate: true,
      deep: true,
    },
    // Re-emit the effective tool list whenever the user toggles a skill
    // upstream (which changes enabledSkillTypes → builtInToolNames).
    // Without this, the parent's formData.tools can drift from what
    // this component actually shows.
    builtInToolNames: {
      handler(val: Set<string>) {
        this.$emit('update:tools', [...val]);
      },
      deep: true,
    },
  },

  mounted() {
    this.loadServers();
    // If the parent didn't pass availableSkills and the store is empty,
    // fetch once so the built-in tool groups render. Harmless no-op when
    // skills are already loaded.
    if (
      !(this.availableSkills && this.availableSkills.length)
      && !(this.agentsStore.availableSkills && this.agentsStore.availableSkills.length)
    ) {
      this.agentsStore.fetchSkills().catch(() => {});
    }
    // Tool-classification metadata (which tools are flagged
    // ``critical``).  Fired here so the wizard's tool list shows
    // the warning indicator the same way the agent-profile page
    // does.  Idempotent — a no-op if already cached.
    this.agentsStore.fetchToolMetadata().catch(() => {});

    // Per-agent overrides — needed so the badge shows the pin for
    // tools the user has already pinned, and so the popover renders
    // the correct initial state.  No-op when ``agentId`` is null
    // (create wizard / standalone surfaces).
    if (this.agentId) {
      this.agentsStore.fetchToolApprovals(this.agentId).catch(() => {});
    }
  },

  methods: {
    toolLabelFor(tool: string): string {
      return toolLabel(this.$t, tool);
    },

    /** Per-tool *configured* gating — what the user sees as "this
     *  tool's policy".  Independent of ``approvalMode``: the mode
     *  decides what happens at runtime (does the policy actually
     *  fire?), but the chip should always render the per-tool
     *  configuration so the user knows what they've set up. */
    effectiveCritical(toolName: string): boolean {
      const overrides = this.agentId
        ? this.agentsStore.getToolApprovalsForAgent(this.agentId)
        : this.localOverrides || {};
      if (toolName in overrides) return overrides[toolName] === true;
      return this.agentsStore.isCriticalTool(toolName);
    },

    /** True when an explicit per-tool override exists (from store
     *  in profile mode, from local buffer in wizard mode). */
    hasOverride(toolName: string): boolean {
      const overrides = this.agentId
        ? this.agentsStore.getToolApprovalsForAgent(this.agentId)
        : this.localOverrides || {};
      return toolName in overrides;
    },

    /** Group-level toggle: flip every tool in this skill group on
     *  or off in one click.  Tri-state checkbox returns ``null``
     *  when going from intermediate → unchecked; treat that as
     *  "off all".  Locked tools are skipped. */
    toggleAllInGroup(
      group: { tools: Array<{ name: string; locked: boolean }> },
      val: boolean | null,
    ) {
      const enable = val === true;
      for (const tool of group.tools) {
        if (tool.locked) continue;
        // Avoid redundant work — toggleBuiltInTool emits three
        // events per call, so skip rows that are already in the
        // requested state.
        const isCurrentlyActive = !this.localDisabledTools.includes(tool.name)
          && (this.isToolFromEnabledSkill(tool.name) || this.localMcpTools.includes(tool.name));
        if (isCurrentlyActive === enable) continue;
        this.toggleBuiltInTool(tool.name, enable);
      }
    },

    toggleBuiltInTool(toolName: string, enable: boolean) {
      // Check if this tool belongs to an enabled skill
      const belongsToEnabledSkill = this.isToolFromEnabledSkill(toolName);

      if (enable) {
        // Remove from disabled list (in case it was there)
        this.localDisabledTools = this.localDisabledTools.filter((t) => t !== toolName);
        // If skill is not enabled, explicitly add via mcp_tools
        if (!belongsToEnabledSkill && !this.localMcpTools.includes(toolName)) {
          this.localMcpTools = [...this.localMcpTools, toolName];
        }
      } else {
        // Remove from explicit mcp_tools if it was there
        this.localMcpTools = this.localMcpTools.filter((t) => t !== toolName);
        // If skill is enabled, add to disabled list to suppress it
        if (belongsToEnabledSkill && !this.localDisabledTools.includes(toolName)) {
          this.localDisabledTools = [...this.localDisabledTools, toolName];
        }
      }
      this.$emit('update:disabledTools', [...this.localDisabledTools]);
      this.$emit('update:mcpTools', [...this.localMcpTools]);
      this.$emit('update:tools', [...this.builtInToolNames]);
    },

    isToolFromEnabledSkill(toolName: string): boolean {
      for (const def of this.effectiveAvailableSkills) {
        if (
          this.enabledSkillTypes.has(def.id)
          && (def.tools || []).includes(toolName)
        ) {
          return true;
        }
      }
      return false;
    },

    async loadServers() {
      this.loading = true;
      this.loadError = null;
      try {
        this.servers = await agentApiService.discoverMcpServers();
        // Auto-expand servers that have selected tools
        for (const server of this.servers) {
          if (this.getSelectedToolCount(server.id) > 0) {
            this.expanded[server.id] = true;
          }
        }
      } catch (err: any) {
        this.loadError = err?.message || this.$t('failed_to_load_mcp_servers');
      } finally {
        this.loading = false;
      }
    },

    toggleExpanded(serverId: string) {
      this.expanded[serverId] = !this.expanded[serverId];
    },

    isToolSelected(serverId: string, toolName: string): boolean {
      if (this.localMcpServers[serverId]?.includes(toolName)) return true;
      // Also check if the tool is included via a selected skill
      return this.builtInToolNames.has(toolName);
    },

    isAllSelected(serverId: string): boolean {
      const server = this.servers.find((s) => s.id === serverId);
      if (!server || !server.tools.length) return false;
      const selected = this.localMcpServers[serverId] || [];
      return selected.length === server.tools.length;
    },

    isPartiallySelected(serverId: string): boolean {
      const count = this.getSelectedToolCount(serverId);
      return count > 0 && !this.isAllSelected(serverId);
    },

    getSelectedToolCount(serverId: string): number {
      return this.localMcpServers[serverId]?.length ?? 0;
    },

    toggleTool(serverId: string, toolName: string, enabled: boolean) {
      const tools = this.localMcpServers[serverId] || [];
      if (enabled) {
        if (!tools.includes(toolName)) {
          this.localMcpServers[serverId] = [...tools, toolName];
        }
      } else {
        const filtered = tools.filter((t) => t !== toolName);
        if (filtered.length > 0) {
          this.localMcpServers[serverId] = filtered;
        } else {
          delete this.localMcpServers[serverId];
        }
      }
      this.emitUpdate();
    },

    toggleAllTools(serverId: string, selectAll: boolean) {
      const server = this.servers.find((s) => s.id === serverId);
      if (!server) return;

      if (selectAll) {
        this.localMcpServers[serverId] = server.tools.map((t) => t.name);
      } else {
        delete this.localMcpServers[serverId];
      }
      this.emitUpdate();
    },

    emitUpdate() {
      // Clone to avoid reactivity issues
      const cleaned: Record<string, string[]> = {};
      for (const [key, val] of Object.entries(this.localMcpServers as Record<string, string[]>)) {
        if (val.length > 0) {
          cleaned[key] = [...val];
        }
      }
      this.$emit('update:modelValue', cleaned);
    },
  },
});
</script>

